   257	static void display_queue_companion_prompt(velawear_display_t *display,
   258	                                           const char *prompt)
   259	{
   260	  velawear_event_t event;
   261	  size_t length;
   262	  int ret;
   263	
   264	  if (display == NULL || display->events == NULL || prompt == NULL)
   265	    {
   266	      return;
   267	    }
   268	
   269	  length = strlen(prompt);
   270	  if (length == 0 || length >= sizeof(event.data.chat.text))
   271	    {
   272	      syslog(LOG_WARNING, "[HCI] Companion prompt length invalid: %lu\n",
   273	             (unsigned long)length);
   274	      return;
   275	    }
   276	
   277	  memset(&event, 0, sizeof(event));
   278	  event.type = VELAWEAR_EVENT_CHAT_INPUT;
   279	  event.priority = VELAWEAR_PRIORITY_HIGH;
   280	  event.timestamp = display_now_ms();
   281	  event.data.chat.length = (int)length;
   282	  memcpy(event.data.chat.text, prompt, length);
   283	  event.data.chat.text[length] = '\0';
   284	  ret = event_manager_push(display->events, &event);
   285	  if (ret < 0)
   286	    {
   287	      syslog(LOG_WARNING, "[HCI] Companion prompt queue failed: %d\n", ret);
   288	      return;
   289	    }
   290	
   291	  display_manager_show_alert(display, "正在联系 AI 陪伴...");
   292	  syslog(LOG_INFO, "[HCI] Companion quick prompt queued bytes=%lu\n",
   293	         (unsigned long)length);
   294	}
