  1122	          lv_obj_clear_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
  1123	          lv_obj_move_foreground(g_alert_overlay);
  1124	        }
  1125	      display->alert_until_ms = now + 60000;
  1126	      display->alert_active = true;
