   480	    {
   481	      return;
   482	    }
   483	
   484	  code = lv_event_get_code(event);
   485	  lv_indev_get_point(indev, &point);
   486	  if (code == LV_EVENT_PRESSED)
   487	    {
   488	      display->touch_start = point;
   489	      display->touch_tracking = true;
   490	      display->touch_swipe_handled = false;
   491	    }
   492	  else if (code == LV_EVENT_GESTURE)
   493	    {
   494	      dir = lv_indev_get_gesture_dir(indev);
   495	      display->touch_swipe_handled = true;
   496	    }
   497	
   498	  memset(&touch_event, 0, sizeof(touch_event));
   499	  touch_event.type = VELAWEAR_EVENT_TOUCH;
   500	  touch_event.priority = VELAWEAR_PRIORITY_NORMAL;
   501	  touch_event.timestamp = display_now_ms();
   502	  touch_event.data.touch.x = point.x;
   503	  touch_event.data.touch.y = point.y;
   504	  touch_event.data.touch.gesture = code == LV_EVENT_GESTURE ?
   505	                                    (int)dir : (int)code;
   506	  if (display->events != NULL &&
   507	      event_manager_push(display->events, &touch_event) < 0)
   508	    {
   509	      syslog(LOG_WARNING, "[Display] Failed to queue touch event\n");
   510	    }
   511	
   512	  if (code == LV_EVENT_RELEASED)
   513	    {
   514	      dx = (int32_t)point.x - (int32_t)display->touch_start.x;
   515	      dy = (int32_t)point.y - (int32_t)display->touch_start.y;
   516	      if (display->touch_tracking && !display->touch_swipe_handled &&
   517	          (dx <= -40 || dx >= 40) &&
   518	          (dx < 0 ? -dx : dx) > (dy < 0 ? -dy : dy))
   519	        {
   520	          display->touch_swipe_handled = true;
   521	          if (dx < 0)
   522	            {
   523	              display_manager_next_page(display);
   524	            }
   525	          else
   526	            {
   527	              display_manager_previous_page(display);
   528	            }
   529	        }
   530	      display->touch_tracking = false;
   531	    }
   532	  else if (code == LV_EVENT_CLICKED)
   533	    {
   534	      if (display->touch_swipe_handled)
   535	        {
   536	          display->touch_swipe_handled = false;
   537	          return;
   538	        }
   539	
   540	      if (display->page_index == VELAWEAR_PAGE_APPS)
   541	        {
   542	          if (display->mvp_app_detail_active)
   543	            {
   544	              if (display->mvp_selected_app == VELAWEAR_APP_AUDIO)
   545	                {
   546	                  ret = display_audio_start(
   547	                    display,
   548	                    point.y < 220 ? DISPLAY_AUDIO_JOB_MELODY :
   549	                                    DISPLAY_AUDIO_JOB_MIC);
   550	                  syslog(LOG_INFO,
   551	                         "[Display] audio app action y=%ld result=%d\n",
   552	                         (long)point.y, ret);
   553	                }
   554	              else if (display->mvp_selected_app == VELAWEAR_APP_MUSIC)
   555	                {
   556	                  ret = display_audio_start(display,
   557	                                             DISPLAY_AUDIO_JOB_MELODY);
   558	                  syslog(LOG_INFO,
   559	                         "[Display] music app action result=%d\n", ret);
   560	                }
   561	              else if (display->mvp_selected_app == VELAWEAR_APP_STOPWATCH)
   562	                {
   563	                  if (point.y < 270)
   564	                    {
   565	                      if (display->stopwatch_running)
   566	                        {
   567	                          display->stopwatch_elapsed_ms +=
   568	                            display_now_ms() -
   569	                            display->stopwatch_started_ms;
   570	                          display->stopwatch_running = false;
   571	                        }
   572	                      else
   573	                        {
   574	                          display->stopwatch_started_ms = display_now_ms();
   575	                          display->stopwatch_running = true;
   576	                        }
   577	                    }
   578	                  else
   579	                    {
   580	                      display->stopwatch_running = false;
   581	                      display->stopwatch_started_ms = 0;
   582	                      display->stopwatch_elapsed_ms = 0;
   583	                    }
   584	                }
   585	              else if (display->mvp_selected_app == VELAWEAR_APP_COMPANION)
   586	                {
   587	                  if (point.y < 220)
   588	                    {
   589	                      display_queue_companion_prompt(
   590	                        display, "今天有点累，陪我聊两句");
   591	                    }
   592	                  else if (point.y < 300)
   593	                    {
   594	                      display_queue_companion_prompt(
   595	                        display, "夸夸我，给我一点鼓励");
   596	                    }
   597	                  else
   598	                    {
   599	                      display_queue_companion_prompt(
   600	                        display, "提醒我休息一下");
   601	                    }
   602	                }
   603	              else
   604	                {
   605	                  display->mvp_app_detail_active = false;
   606	                }
   607	
   608	              display->last_update_ms = 0;
   609	              return;
   610	            }
   611	
   612	          if (point.y >= 115 &&
   613	              point.y < 115 + 27 * VELAWEAR_APP_COUNT)
   614	            {
   615	              app_index = ((int)point.y - 115) / 27;
   616	              if (app_index >= 0 && app_index < VELAWEAR_APP_COUNT)
   617	                {
   618	                  display->mvp_selected_app = (uint8_t)app_index;
   619	                  display->mvp_app_detail_active = true;
   620	                  display->last_update_ms = 0;
   621	                }
   622	            }
   623	          return;
   624	        }
   625	
   626	      display_manager_set_page(display,
   627	                               display->page_index == VELAWEAR_PAGE_WATCHFACE ?
   628	                               VELAWEAR_PAGE_APPS : VELAWEAR_PAGE_WATCHFACE);
   629	    }
   630	  else if (code == LV_EVENT_LONG_PRESSED)
   631	    {
   632	      display->touch_swipe_handled = true;
   633	      display_manager_set_page(display, VELAWEAR_PAGE_WATCHFACE);
   634	    }
   635	  else if ((dir & LV_DIR_LEFT) != 0 || (dir & LV_DIR_TOP) != 0)
   636	    {
   637	      display_manager_next_page(display);
   638	    }
   639	  else if ((dir & LV_DIR_RIGHT) != 0 || (dir & LV_DIR_BOTTOM) != 0)
   640	    {
   641	      display_manager_previous_page(display);
   642	    }
   643	}

