   734	static void display_render_app(velawear_display_t *display,
   735	                               const velawear_state_t *state)
   736	{
   737	  char content[384];
   738	  uint32_t elapsed;
   739	  uint32_t minutes;
   740	  uint32_t seconds;
   741	  uint32_t tenths;
   742	
   743	  if (display == NULL || state == NULL || !display->detail_active ||
   744	      display->metrics_label == NULL)
   745	    {
   746	      return;
   747	    }
   748	
   749	  content[0] = '\0';
   750	  switch ((velawear_display_app_t)display->active_app)
   751	    {
   752	      case VELAWEAR_APP_AUDIO:
   753	        snprintf(content, sizeof(content),
   754	                 "喇叭\n等待测试\n\n麦克风\n点击检查设备");
   755	        break;
   756	
   757	      case VELAWEAR_APP_MUSIC:
   758	        snprintf(content, sizeof(content),
   759	                 "内置旋律\n\n准备播放\n音量 70%%");
   760	        break;
   761	
   762	      case VELAWEAR_APP_MOTION:
   763	        snprintf(content, sizeof(content),
   764	                 "运动  %s\n跑步  %s\n今日活动 %lu\n运行时间 %lu 秒",
   765	                 state->is_moving ? "活动" : "静止",
   766	                 state->is_running ? "是" : "否",
   767	                 (unsigned long)state->move_count_today,
   768	                 (unsigned long)state->uptime_seconds);
   769	        break;
   770	
   771	      case VELAWEAR_APP_STOPWATCH:
   772	        elapsed = display->stopwatch_elapsed_ms;
   773	        if (display->stopwatch_running)
   774	          {
   775	            elapsed += display_now_ms() - display->stopwatch_started_ms;
   776	          }
   777	        minutes = elapsed / 60000;
   778	        seconds = (elapsed / 1000) % 60;
   779	        tenths = (elapsed / 100) % 10;
   780	        snprintf(content, sizeof(content), "%02lu:%02lu.%lu\n\n%s",
   781	                 (unsigned long)minutes, (unsigned long)seconds,
   782	                 (unsigned long)tenths,
