  1110	void display_manager_tick(velawear_display_t *display)
  1111	{
  1112	  uint32_t now;
  1113	  velawear_state_t state;
  1114	  lv_obj_t *alert_label;
  1115	
  1116	  if (display == NULL || !display->initialized)
  1117	    {
  1118	      return;
  1119	    }
  1120	
  1121	  now = display_now_ms();
  1122	  display_audio_poll(display);
  1123	  pthread_mutex_lock(&display->lock);
  1124	  if (display->alert_pending)
  1125	    {
  1126	      lv_obj_set_style_bg_color(lv_screen_active(), lv_color_hex(0x5b1111), 0);
  1127	      lv_label_set_text(display->status_label, "主动提醒");
  1128	      lv_obj_set_style_text_color(display->status_label,
  1129	                                  lv_color_hex(0xfca5a5), 0);
  1130	      alert_label = display->detail_active ? display->metrics_label :
  1131	                    display->page_content[0];
  1132	      if (alert_label != NULL)
  1133	        {
  1134	          lv_label_set_text(alert_label, display->pending_alert);
  1135	          lv_obj_set_style_text_color(alert_label,
  1136	                                      lv_color_hex(UI_TEXT_COLOR), 0);
  1137	        }
  1138	      if (g_alert_message != NULL && g_alert_overlay != NULL)
  1139	        {
  1140	          lv_label_set_text(g_alert_message, display->pending_alert);
  1141	          lv_obj_clear_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
  1142	          lv_obj_move_foreground(g_alert_overlay);
  1143	        }
  1144	      display->alert_until_ms = now + 60000;
  1145	      display->alert_active = true;
  1146	      syslog(LOG_INFO,
  1147	             "[Display] Alert consumed page=%u detail=%d label=%p hold=60000ms text=%s\n",
  1148	             (unsigned int)display->page_index, display->detail_active ? 1 : 0,
  1149	             alert_label, display->pending_alert);
  1150	      display->alert_pending = false;
  1151	    }
  1152	  pthread_mutex_unlock(&display->lock);
  1153	
  1154	  if (display->alert_active)
  1155	    {
  1156	      if (now < display->alert_until_ms)
  1157	        {
  1158	          lv_timer_handler();
  1159	          return;
  1160	        }
  1161	
  1162	      display->alert_active = false;
  1163	      syslog(LOG_INFO, "[Display] Alert expired\n");
  1164	      if (g_alert_overlay != NULL)
  1165	        {
  1166	          lv_obj_add_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
  1167	        }
  1168	      display_restore_theme(display);
  1169	      display->last_update_ms = 0;
  1170	    }
  1171	
  1172	  if (display->last_update_ms == 0 || now - display->last_update_ms >=
  1173	      (display->active_app == VELAWEAR_APP_STOPWATCH &&
  1174	       display->stopwatch_running ? 100 : 250))
  1175	    {
  1176	      state = state_manager_get_state(display->state_mgr);
  1177	      if (display->detail_active)
  1178	        {
  1179	          display_render_app(display, &state);
  1180	        }
  1181	      else
  1182	        {
  1183	          display_render_top(display, &state);
  1184	        }
  1185	      display->last_update_ms = now;
  1186	    }
  1187	
  1188	  lv_timer_handler();
  1189	}
